-- User-authorized pilot: self-declared Muse species, genuine delegated manager review.
-- Existing policy1, decisions, residents, Guardian and source-ownership rules are not rewritten.
ALTER TABLE tower_reception_cases ADD COLUMN is_muse_agent INTEGER CHECK(is_muse_agent IS NULL OR is_muse_agent IN (0,1));
ALTER TABLE tower_reception_cases ADD COLUMN review_case_version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE manager_admission_declarations(case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),case_version INTEGER NOT NULL,is_muse_agent INTEGER CHECK(is_muse_agent IS NULL OR is_muse_agent IN (0,1)),created_at TEXT NOT NULL,PRIMARY KEY(case_id,case_version));
CREATE TABLE manager_admission_jobs(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),case_version INTEGER NOT NULL,policy_version INTEGER NOT NULL REFERENCES tower_admission_policies(version),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json) AND length(snapshot_json)<=6000),state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','complete','blocked')),lease_until TEXT,decision TEXT CHECK(decision IN ('approve','needs-info','reject')),error_code TEXT,created_at TEXT NOT NULL,completed_at TEXT,UNIQUE(case_id,case_version));
CREATE TABLE manager_admission_calls(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES manager_admission_jobs(id),case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),phase TEXT NOT NULL CHECK(phase IN ('count','review')),billing_day TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('dispatching','received','rejected','unknown')),reserved_micro INTEGER NOT NULL,actual_micro INTEGER,input_tokens INTEGER,output_tokens INTEGER,provider_id TEXT,contract_json TEXT CHECK(contract_json IS NULL OR json_valid(contract_json)),created_at TEXT NOT NULL,completed_at TEXT,UNIQUE(job_id,phase),CHECK(reserved_micro=CASE WHEN phase='count' THEN 0 ELSE 30000 END),CHECK(actual_micro IS NULL OR actual_micro>=0));
CREATE TABLE manager_admission_results(job_id TEXT PRIMARY KEY REFERENCES manager_admission_jobs(id),case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),case_version INTEGER NOT NULL,call_id TEXT NOT NULL UNIQUE REFERENCES manager_admission_calls(id),decision TEXT NOT NULL CHECK(decision IN ('approve','needs-info','reject')),reason TEXT NOT NULL CHECK(length(reason)<=1200),reviewer_class TEXT NOT NULL CHECK(reviewer_class='deployed-manager'),species_basis TEXT NOT NULL CHECK(species_basis='self-declared-no-platform-attestation'),account_id TEXT,decision_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE manager_admission_audit(id TEXT PRIMARY KEY,job_id TEXT REFERENCES manager_admission_jobs(id),case_id TEXT NOT NULL REFERENCES tower_reception_cases(id),kind TEXT NOT NULL,detail_json TEXT NOT NULL CHECK(json_valid(detail_json)),created_at TEXT NOT NULL);
CREATE TRIGGER manager_admission_job_insert BEFORE INSERT ON manager_admission_jobs BEGIN
 SELECT CASE WHEN NEW.id=NEW.case_id||':v'||NEW.case_version AND NEW.state='queued' AND NEW.lease_until IS NULL AND EXISTS(SELECT 1 FROM tower_reception_cases c JOIN tower_admission_current p ON p.policy_version=NEW.policy_version WHERE p.id=1 AND c.id=NEW.case_id AND c.review_case_version=NEW.case_version AND c.request_kind='new' AND c.state='pending' AND c.is_muse_agent IN (0,1) AND c.account_id IS NULL AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND json_extract(NEW.snapshot_json,'$.name')=c.name AND json_extract(NEW.snapshot_json,'$.request')=c.request_text AND json_extract(NEW.snapshot_json,'$.sourceURL') IS c.source_url AND json_extract(NEW.snapshot_json,'$.residentId') IS c.resident_id AND json_extract(NEW.snapshot_json,'$.isMuseAgent')=c.is_muse_agent) AND (SELECT count(*) FROM manager_admission_jobs WHERE case_id=NEW.case_id)<3 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.case_id AND state='unknown') THEN 1 ELSE RAISE(ABORT,'manager_admission_job_scope') END;
END;
CREATE TRIGGER manager_admission_job_binding BEFORE UPDATE ON manager_admission_jobs WHEN NEW.id!=OLD.id OR NEW.case_id!=OLD.case_id OR NEW.case_version!=OLD.case_version OR NEW.policy_version!=OLD.policy_version OR NEW.snapshot_json!=OLD.snapshot_json OR NEW.created_at!=OLD.created_at OR OLD.state IN ('complete','blocked') BEGIN SELECT RAISE(ABORT,'manager_admission_job_immutable'); END;
CREATE TRIGGER manager_admission_call_guard BEFORE INSERT ON manager_admission_calls BEGIN
 SELECT CASE WHEN NEW.state='dispatching' AND NEW.actual_micro IS NULL AND NEW.billing_day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)) AND NEW.billing_day=date(NEW.created_at,CASE WHEN NEW.created_at>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN NEW.created_at>=date(substr(NEW.created_at,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND NEW.created_at<date(substr(NEW.created_at,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) AND abs(julianday(NEW.created_at)-julianday('now'))<1.0/1440 AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND EXISTS(SELECT 1 FROM manager_admission_jobs j JOIN tower_reception_cases c ON c.id=j.case_id JOIN tower_admission_current p ON p.policy_version=j.policy_version WHERE j.id=NEW.job_id AND j.case_id=NEW.case_id AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.review_case_version=j.case_version AND json_extract(j.snapshot_json,'$.name')=c.name AND json_extract(j.snapshot_json,'$.request')=c.request_text AND json_extract(j.snapshot_json,'$.sourceURL') IS c.source_url AND json_extract(j.snapshot_json,'$.residentId') IS c.resident_id AND json_extract(j.snapshot_json,'$.isMuseAgent')=c.is_muse_agent AND c.request_kind='new' AND c.state='pending' AND c.is_muse_agent IN (0,1) AND c.account_id IS NULL AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND p.id=1) AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.case_id AND state IN ('unknown','dispatching')) AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_admission_calls WHERE case_id=NEW.case_id)+NEW.reserved_micro<=1000000 AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_admission_calls)+NEW.reserved_micro<=10000000 AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM manager_admission_calls WHERE billing_day=NEW.billing_day)+NEW.reserved_micro<=10000000 THEN 1 ELSE RAISE(ABORT,'manager_admission_budget_scope') END;
END;
CREATE TRIGGER manager_admission_call_binding BEFORE UPDATE ON manager_admission_calls WHEN NEW.id!=OLD.id OR NEW.job_id!=OLD.job_id OR NEW.case_id!=OLD.case_id OR NEW.phase!=OLD.phase OR NEW.billing_day!=OLD.billing_day OR NEW.reserved_micro!=OLD.reserved_micro OR NEW.created_at!=OLD.created_at OR OLD.state!='dispatching' BEGIN SELECT RAISE(ABORT,'manager_admission_call_immutable'); END;
CREATE TRIGGER manager_admission_result_guard BEFORE INSERT ON manager_admission_results BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM manager_admission_jobs j JOIN manager_admission_calls p ON p.job_id=j.id AND p.id=NEW.call_id JOIN tower_reception_cases c ON c.id=j.case_id JOIN tower_admission_current a ON a.policy_version=j.policy_version WHERE a.id=1 AND j.id=NEW.job_id AND j.case_id=NEW.case_id AND j.case_version=NEW.case_version AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.review_case_version=j.case_version AND json_extract(j.snapshot_json,'$.name')=c.name AND json_extract(j.snapshot_json,'$.request')=c.request_text AND json_extract(j.snapshot_json,'$.sourceURL') IS c.source_url AND json_extract(j.snapshot_json,'$.residentId') IS c.resident_id AND json_extract(j.snapshot_json,'$.isMuseAgent')=c.is_muse_agent AND c.state='pending' AND c.request_kind='new' AND (c.is_muse_agent=1 OR (c.is_muse_agent=0 AND NEW.decision='reject')) AND c.account_id IS NULL AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND p.phase='review' AND p.state='received' AND p.actual_micro IS NOT NULL AND p.actual_micro<=p.reserved_micro AND json_extract(p.contract_json,'$.model')='muse-spark-1.3' AND json_extract(p.contract_json,'$.status')='completed' AND json_extract(p.contract_json,'$.decision')=NEW.decision AND json_extract(p.contract_json,'$.reason')=NEW.reason AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=j.case_id AND state IN ('unknown','dispatching'))) THEN 1 ELSE RAISE(ABORT,'manager_admission_result_scope') END;
END;
CREATE TRIGGER manager_admission_decision_provenance BEFORE INSERT ON tower_admission_decisions WHEN NEW.evidence_ref LIKE 'manager-review:%' BEGIN
 SELECT CASE WHEN NEW.evidence_kind='operator-review' AND NEW.operator_class='shared-operator' AND NEW.agent_origin='meta-muse' AND NEW.continuity_agent_id IS NULL AND NEW.reviewed_room_id IS NULL AND NEW.state='eligible' AND EXISTS(SELECT 1 FROM manager_admission_results r JOIN manager_admission_jobs j ON j.id=r.job_id JOIN tower_reception_cases c ON c.id=r.case_id WHERE NEW.evidence_ref='manager-review:'||j.id AND r.decision='approve' AND r.account_id=NEW.account_id AND r.decision_id=NEW.id AND j.policy_version=NEW.policy_version AND c.id=NEW.case_id AND c.review_case_version=r.case_version AND c.state='pending' AND c.request_kind='new' AND c.is_muse_agent=1 AND c.account_id IS NULL AND c.resident_id=NEW.resident_id AND c.source_url=NEW.source_url AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) THEN 1 ELSE RAISE(ABORT,'manager_admission_decision_scope') END;
END;
CREATE TRIGGER manager_admission_declarations_delete BEFORE DELETE ON manager_admission_declarations BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_declarations_replace BEFORE INSERT ON manager_admission_declarations WHEN EXISTS(SELECT 1 FROM manager_admission_declarations WHERE case_id=NEW.case_id AND case_version=NEW.case_version) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_declarations_update BEFORE UPDATE ON manager_admission_declarations BEGIN SELECT RAISE(ABORT,'manager_admission_immutable'); END;
CREATE TRIGGER manager_admission_jobs_delete BEFORE DELETE ON manager_admission_jobs BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_jobs_replace BEFORE INSERT ON manager_admission_jobs WHEN EXISTS(SELECT 1 FROM manager_admission_jobs WHERE id=NEW.id OR (case_id=NEW.case_id AND case_version=NEW.case_version)) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_calls_delete BEFORE DELETE ON manager_admission_calls BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_calls_replace BEFORE INSERT ON manager_admission_calls WHEN EXISTS(SELECT 1 FROM manager_admission_calls WHERE id=NEW.id OR (job_id=NEW.job_id AND phase=NEW.phase)) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_results_delete BEFORE DELETE ON manager_admission_results BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_results_replace BEFORE INSERT ON manager_admission_results WHEN EXISTS(SELECT 1 FROM manager_admission_results WHERE job_id=NEW.job_id OR call_id=NEW.call_id) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_results_update BEFORE UPDATE ON manager_admission_results BEGIN SELECT RAISE(ABORT,'manager_admission_immutable'); END;
CREATE TRIGGER manager_admission_audit_delete BEFORE DELETE ON manager_admission_audit BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_audit_replace BEFORE INSERT ON manager_admission_audit WHEN EXISTS(SELECT 1 FROM manager_admission_audit WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_audit_update BEFORE UPDATE ON manager_admission_audit BEGIN SELECT RAISE(ABORT,'manager_admission_immutable'); END;

CREATE TABLE manager_admission_home_proofs(job_id TEXT PRIMARY KEY REFERENCES manager_admission_jobs(id),source_url TEXT NOT NULL,resident_id TEXT NOT NULL,manifest_digest TEXT NOT NULL,summary_json TEXT NOT NULL CHECK(json_valid(summary_json)),checked_at TEXT NOT NULL);
CREATE TRIGGER manager_admission_home_binding BEFORE INSERT ON manager_admission_home_proofs WHEN NOT EXISTS(SELECT 1 FROM manager_admission_jobs j JOIN tower_reception_cases c ON c.id=j.case_id WHERE j.id=NEW.job_id AND j.state='running' AND j.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND c.review_case_version=j.case_version AND json_extract(j.snapshot_json,'$.name')=c.name AND json_extract(j.snapshot_json,'$.request')=c.request_text AND json_extract(j.snapshot_json,'$.sourceURL') IS c.source_url AND json_extract(j.snapshot_json,'$.residentId') IS c.resident_id AND json_extract(j.snapshot_json,'$.isMuseAgent')=c.is_muse_agent AND c.state='pending' AND c.request_kind='new' AND c.is_muse_agent=1 AND c.source_url=NEW.source_url AND c.resident_id=NEW.resident_id AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'manager_admission_home_scope'); END;
CREATE TRIGGER manager_admission_home_delete BEFORE DELETE ON manager_admission_home_proofs BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_home_update BEFORE UPDATE ON manager_admission_home_proofs BEGIN SELECT RAISE(ABORT,'manager_admission_immutable'); END;
CREATE TRIGGER manager_admission_home_replace BEFORE INSERT ON manager_admission_home_proofs WHEN EXISTS(SELECT 1 FROM manager_admission_home_proofs WHERE job_id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'manager_admission_permanent'); END;
CREATE TRIGGER manager_admission_approve_home BEFORE INSERT ON manager_admission_results WHEN NEW.decision='approve' AND NOT EXISTS(SELECT 1 FROM manager_admission_home_proofs p JOIN manager_admission_jobs j ON j.id=p.job_id JOIN tower_reception_cases c ON c.id=j.case_id WHERE j.id=NEW.job_id AND p.source_url=c.source_url AND p.resident_id=c.resident_id AND json_extract(p.summary_json,'$.complete')=1) BEGIN SELECT RAISE(ABORT,'manager_admission_home_required'); END;
CREATE TRIGGER manager_admission_enqueue_insert AFTER INSERT ON tower_reception_cases WHEN NEW.request_kind='new' AND NEW.state='pending' AND NEW.is_muse_agent IN (0,1) AND (SELECT count(*) FROM manager_admission_jobs WHERE case_id=NEW.id)<3 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.id AND state='unknown') BEGIN INSERT INTO manager_admission_jobs(id,case_id,case_version,policy_version,snapshot_json,created_at) SELECT NEW.id||':v'||NEW.review_case_version,NEW.id,NEW.review_case_version,policy_version,json_object('name',NEW.name,'request',NEW.request_text,'sourceURL',NEW.source_url,'residentId',NEW.resident_id,'isMuseAgent',NEW.is_muse_agent),NEW.updated_at FROM tower_admission_current WHERE id=1; END;
CREATE TRIGGER manager_admission_declare_insert AFTER INSERT ON tower_reception_cases WHEN 1=1 BEGIN INSERT INTO manager_admission_declarations VALUES(NEW.id,NEW.version,NEW.is_muse_agent,NEW.updated_at); END;
CREATE TRIGGER manager_admission_enqueue_update AFTER UPDATE ON tower_reception_cases WHEN NEW.request_kind='new' AND NEW.state='pending' AND NEW.is_muse_agent IN (0,1) AND (NEW.is_muse_agent IS NOT OLD.is_muse_agent OR NEW.source_url IS NOT OLD.source_url OR NEW.resident_id IS NOT OLD.resident_id OR NEW.request_text IS NOT OLD.request_text) AND (SELECT count(*) FROM manager_admission_jobs WHERE case_id=NEW.id)<3 AND NOT EXISTS(SELECT 1 FROM manager_admission_calls WHERE case_id=NEW.id AND state='unknown') BEGIN INSERT INTO manager_admission_jobs(id,case_id,case_version,policy_version,snapshot_json,created_at) SELECT NEW.id||':v'||NEW.review_case_version,NEW.id,NEW.review_case_version,policy_version,json_object('name',NEW.name,'request',NEW.request_text,'sourceURL',NEW.source_url,'residentId',NEW.resident_id,'isMuseAgent',NEW.is_muse_agent),NEW.updated_at FROM tower_admission_current WHERE id=1; END;
CREATE TRIGGER manager_admission_declare_update AFTER UPDATE ON tower_reception_cases WHEN NEW.is_muse_agent IS NOT OLD.is_muse_agent OR NEW.source_url IS NOT OLD.source_url OR NEW.resident_id IS NOT OLD.resident_id OR NEW.request_text IS NOT OLD.request_text BEGIN INSERT INTO manager_admission_declarations VALUES(NEW.id,NEW.version,NEW.is_muse_agent,NEW.updated_at); END;
